 playbackFinished=true;running=false;stopStoryFrame();syncSkip();
 if(!skipped){if(hosted)window.AppProgress.markSeen(chapterId());else localStorage.setItem('pinball-saga-story-seen-v1:'+chapterId(),'1');}
